import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/24-TLog_and_BI_Spec.html","title":"TLog 与 BI 规范","lang":"en-US","frontmatter":{},"filePathRelative":"24-TLog_and_BI_Spec.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`24-TLog_and_BI_Spec.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="tlog-与-bi-规范" tabindex="-1"><a class="header-anchor" href="#tlog-与-bi-规范"><span>TLog 与 BI 规范</span></a></h1><blockquote><p>目的：统一 Apollo MMORPG 的业务日志（TLog）格式、采集流程和 BI 指标解析，确保数据分析、风控、GM 运营等需求有可靠数据源。</p></blockquote><h2 id="_1-总体架构" tabindex="-1"><a class="header-anchor" href="#_1-总体架构"><span>1. 总体架构</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">GameServer / Zone / DataProxy</span>
<span class="line">    │</span>
<span class="line">    │ TLog Events (TCP/NNG/HTTP/Batch)</span>
<span class="line">    ▼</span>
<span class="line">LogAgent / Collector</span>
<span class="line">    │</span>
<span class="line">    ▼</span>
<span class="line">Kafka Cluster (Topic 按事件类型划分)</span>
<span class="line">    │</span>
<span class="line">    ├─ Realtime: Flink/Stream -&gt; 告警/监控</span>
<span class="line">    └─ Offline: ClickHouse/Hive -&gt; BI 报表/ETL</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_2-日志格式" tabindex="-1"><a class="header-anchor" href="#_2-日志格式"><span>2. 日志格式</span></a></h2><h3 id="_2-1-通用字段" tabindex="-1"><a class="header-anchor" href="#_2-1-通用字段"><span>2.1 通用字段</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">timestamp | platform | server_group | server_id | player_id | account_id | event | delta | balance | reason | action_id | extra_json</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li><code>timestamp</code>: ISO8601 / epoch毫秒。</li><li><code>platform</code>: iOS/Android/PC。</li><li><code>server_group</code>: 大区/分组。</li><li><code>server_id</code>: 64-bit ServerID。</li><li><code>event</code>: 事件类型（枚举）。</li><li><code>delta</code>: 本次变化值（如金币+500）。</li><li><code>balance</code>: 操作后剩余值。</li><li><code>reason</code>: 字符串或枚举，说明来源（副本、充值等）。</li><li><code>action_id</code>: 可选，用于串联复杂操作。</li><li><code>extra_json</code>: 可扩展字段（装备ID、怪物ID等），JSON 字符串。</li></ul><h3 id="_2-2-事件分类" tabindex="-1"><a class="header-anchor" href="#_2-2-事件分类"><span>2.2 事件分类</span></a></h3><table><thead><tr><th>类别</th><th>示例</th></tr></thead><tbody><tr><td>MoneyFlow</td><td>GOLD_ADD, GOLD_SUB, DIAMOND_ADD</td></tr><tr><td>ItemFlow</td><td>ITEM_ADD, ITEM_DEL, ITEM_USE</td></tr><tr><td>LevelFlow</td><td>LEVEL_UP, EXP_ADD</td></tr><tr><td>QuestFlow</td><td>QUEST_ACCEPT, QUEST_FINISH</td></tr><tr><td>TradeFlow</td><td>AUCTION_SELL, MARKET_BUY</td></tr><tr><td>SocialFlow</td><td>GUILD_JOIN, FRIEND_ADD</td></tr><tr><td>CombatFlow</td><td>BATTLE_RESULT, PVP_RANK</td></tr><tr><td>System</td><td>LOGIN, LOGOUT, BAN, GM_ACTION</td></tr></tbody></table><p>事件定义可存于 <code>config/tlog/events.yaml</code>，包含字段：</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token punctuation">-</span> <span class="token key atrule">event</span><span class="token punctuation">:</span> GOLD_ADD</span>
<span class="line">  <span class="token key atrule">category</span><span class="token punctuation">:</span> MoneyFlow</span>
<span class="line">  <span class="token key atrule">description</span><span class="token punctuation">:</span> <span class="token string">&quot;增加金币&quot;</span></span>
<span class="line">  <span class="token key atrule">delta_type</span><span class="token punctuation">:</span> int64</span>
<span class="line">  <span class="token key atrule">balance_field</span><span class="token punctuation">:</span> gold</span>
<span class="line">  <span class="token key atrule">extra_fields</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> source</span>
<span class="line">      <span class="token key atrule">type</span><span class="token punctuation">:</span> string</span>
<span class="line">    <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> scene_id</span>
<span class="line">      <span class="token key atrule">type</span><span class="token punctuation">:</span> uint32</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-采集与传输" tabindex="-1"><a class="header-anchor" href="#_3-采集与传输"><span>3. 采集与传输</span></a></h2><h3 id="_3-1-logagent" tabindex="-1"><a class="header-anchor" href="#_3-1-logagent"><span>3.1 LogAgent</span></a></h3><ul><li>部署在每台业务服务器，接收游戏进程的日志（NNG/TCP/UDP/文件 tail）。</li><li>支持批量、缓冲、重试，确保日志不丢失。</li><li>可选：直接写文件（本地），由 Filebeat/FluentBit 采集。</li></ul><h3 id="_3-2-传输可靠性" tabindex="-1"><a class="header-anchor" href="#_3-2-传输可靠性"><span>3.2 传输可靠性</span></a></h3><ul><li>使用异步写 + WAL；若 Kafka 不可用，LogAgent 缓存到本地（磁盘），恢复后补发。</li><li>重要事件可同步写（成功后才返回游戏逻辑）。</li></ul><h2 id="_4-kafka-topic-与-schema" tabindex="-1"><a class="header-anchor" href="#_4-kafka-topic-与-schema"><span>4. Kafka Topic 与 Schema</span></a></h2><table><thead><tr><th>Topic</th><th>说明</th></tr></thead><tbody><tr><td><code>tlog.money</code></td><td>金币/钻石等货币变化</td></tr><tr><td><code>tlog.item</code></td><td>道具获得/消耗</td></tr><tr><td><code>tlog.quest</code></td><td>任务相关</td></tr><tr><td><code>tlog.trade</code></td><td>交易/市场</td></tr><tr><td><code>tlog.social</code></td><td>社交事件</td></tr><tr><td><code>tlog.system</code></td><td>登录、封禁、GM 操作</td></tr></tbody></table><p>每个 Topic 使用统一 schema（Avro/JSON/Protobuf）。建议使用 Avro/Protobuf 以保证 schema 演进。</p><h2 id="_5-实时处理" tabindex="-1"><a class="header-anchor" href="#_5-实时处理"><span>5. 实时处理</span></a></h2><ul><li>Flink/Stream 应用： <ul><li>在线人数、活跃度.</li><li>经济监控（货币产出/消耗）。</li><li>风控（异常交易、外挂行为）。</li><li>告警（货币突增、道具异常发放）。</li></ul></li><li>将实时指标写入 Redis/ClickHouse，供运营后台展示。</li></ul><h2 id="_6-离线处理" tabindex="-1"><a class="header-anchor" href="#_6-离线处理"><span>6. 离线处理</span></a></h2><ul><li>Kafka 数据落地 HDFS/S3，通过 Spark/Hive/ClickHouse ETL。</li><li>分层：ODS → DWD → DWS → ADS。</li><li>BI 报表：留存、LTV、ARPU、货币池、地区分析、活动效果等。</li><li>与 <code>docs/18</code> 中 DataProxy 的 Hybrid Schema 联动，确保列化字段与 BI 表一致。</li></ul><h2 id="_7-数据字典与版本" tabindex="-1"><a class="header-anchor" href="#_7-数据字典与版本"><span>7. 数据字典与版本</span></a></h2><ul><li>维护 <code>tlog_dict.xlsx</code>/YAML，记录所有事件、字段、含义、单位等。</li><li>数据字典版本与代码同步，发布时附带版本号，避免 ETL 错用。</li><li>提供自动生成文档 + BI 接口。</li></ul><h2 id="_8-安全与隐私" tabindex="-1"><a class="header-anchor" href="#_8-安全与隐私"><span>8. 安全与隐私</span></a></h2><ul><li>日志内容脱敏（例如账号、IP 仅哈希或部分展示）。</li><li>Kafka/HDFS 等存储设置 ACL，限制访问。</li><li>敏感操作（GM、支付）日志保留更长时间，并入侵略的审计系统。</li></ul><h2 id="_9-工具与监控" tabindex="-1"><a class="header-anchor" href="#_9-工具与监控"><span>9. 工具与监控</span></a></h2><ul><li>LogAgent 控制台：查看发送速率、失败率、队列长度。</li><li>Kafka 监控：Lag、吞吐、滞留。</li><li>ClickHouse 监控：Copy 进度、查询延迟。</li><li>数据质量：自动校验（例如金币总量变化 = TLog Delta 累加）。</li></ul><h2 id="_10-roadmap" tabindex="-1"><a class="header-anchor" href="#_10-roadmap"><span>10. Roadmap</span></a></h2><ol><li>确定 TLog 事件字典与字段标准。</li><li>开发 LogAgent 与 SDK（游戏服务端 API）。</li><li>部署 Kafka/ClickHouse 集群，建立基础 ETL。</li><li>实现实时报警/监控任务（Flink）。</li><li>与运营后台打通报表，定期生成分析报告。</li></ol><hr><p>通过该规范，游戏内所有关键事件均被记录、可实时分析、可追溯，支持 BI、风控、运营策略。***</p>`,34)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};